import {readFile} from 'node:fs/promises';
const version='20260917000100',name='remove_retired_test_orders';
const source=(await readFile(`supabase/migrations/${version}_${name}.sql`,'utf8')).replaceAll('\r',''),literal="'"+source.replaceAll("'","''")+"'";
const verify=`select exists(select 1 from supabase_migrations.schema_migrations where version='${version}') registered,count(*)::int remaining from public.wc_orders where id in ('f076f530-6be8-458b-9606-693e0153c101','f076f530-6be8-458b-9606-693e0153c102') or order_number in ('TEST-BACKDROP','TEST-CART');`;
const sql=`begin;select pg_advisory_xact_lock(${version});do $release$ begin if exists(select 1 from supabase_migrations.schema_migrations where version='${version}') then if (select replace(statements[1],E'\\r','') from supabase_migrations.schema_migrations where version='${version}') is distinct from replace(${literal},E'\\r','') then raise exception 'Migration differs';end if;else execute ${literal};insert into supabase_migrations.schema_migrations(version,name,statements) values('${version}','${name}',array[${literal}]);end if;end $release$;commit;${verify}`;
if(process.argv.includes('--print-sql')){process.stdout.write(sql);process.exit(0);}
const token=process.env.SUPABASE_ACCESS_TOKEN;if(!token)throw Error('Supabase access token required');
async function query(query,read_only){const response=await fetch('https://api.supabase.com/v1/projects/zgvnrpspwluapaxnycrg/database/query',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({query,read_only})});if(!response.ok)throw Error(`Production query failed: HTTP ${response.status}: ${(await response.text()).slice(0,500)}`);return response.json();}
if(process.argv.includes('--apply')){await query(sql,false);const rows=await query(verify,true);if(!rows[0]?.registered||rows[0]?.remaining!==0)throw Error('Postflight failed');console.log('Verified:',JSON.stringify(rows));}
